    double numRecordedBitsAsDouble = numRecordedBits;

    double saturation = numRecordedBitsAsDouble / setSizeAsDouble;
    double logInverseSaturation = -Math.Log(1 - saturation);

    return (int)(setSizeAsDouble * logInverseSaturation);
}

