public static Transport Open(URIish uri)
{
    foreach (WeakReference<TransportProtocol> weakRef in protocols)
    {
        TransportProtocol proto;
        if (!weakRef.TryGetTarget(out proto) || proto == null)
        {
            protocols.Remove(weakRef);
            continue;
        }

        if (proto.CanHandle(uri, null, null))
            return proto.Open(uri);
    }

    throw new NotSupportedException(
        string.Format(JGitText.Get().URINotSupported, uri));
}

