public string GetText(Interval interval)
{
    int start = interval.a;
    int stop = interval.b;

    if (start < 0 || stop < 0)
        return string.Empty;

    Fill();

    if (stop >= tokens.Count)
        stop = tokens.Count - 1;

    var buf = new System.Text.StringBuilder();

    for (int i = start; i <= stop; i++)
    {
        Token t = tokens[i];
        if (t.Type == Token.EOF)
            break;

        buf.Append(t.Text);
    }

    return buf.ToString();
}

