public FileMode GetIndexFileMode(DirCacheIterator indexIter)
{
    FileMode wtMode = GetEntryFileMode();

    if (indexIter == null)
        return wtMode;

    FileMode iMode = indexIter.GetEntryFileMode();

    // If file‑mode is forced and the index entry is not a gitlink or a tree,
    // keep the working‑tree mode.
    if (GetOptions().IsFileMode && iMode != FileMode.GITLINK && iMode != FileMode.TREE)
        return wtMode;

    // When file‑mode is not forced, allow executable bits to be taken from the index.
    if (!GetOptions().IsFileMode)
    {
        if (wtMode == FileMode.REGULAR_FILE && iMode == FileMode.EXECUTABLE_FILE)
            return iMode;

        if (wtMode == FileMode.EXECUTABLE_FILE && iMode == FileMode.REGULAR_FILE)
            return iMode;
    }

    // Gitlink vs. tree handling.
    if (iMode == FileMode.GITLINK && wtMode == FileMode.TREE && !GetOptions().IsDirNoGitLinks)
        return iMode;

    if (iMode == FileMode.TREE && wtMode == FileMode.GITLINK)
        return iMode;

    // Default to the working‑tree mode.
    return wtMode;
}

