public static bool? CoerceValueToBoolean(ValueEval ve, bool stringsAreBlanks)
{
    // Null or blank evaluates to a null Boolean
    if (ve == null || ve == BlankEval.Instance)
        return null;

    // Boolean values are returned directly
    if (ve is BoolEval boolEval)
        return boolEval.GetBooleanValue();

    // Strings can be treated as blanks or parsed as true/false
    if (ve is StringEval stringEval)
    {
        if (stringsAreBlanks)
            return null;

        string str = stringEval.GetStringValue();

        if (string.Equals(str, "true", StringComparison.OrdinalIgnoreCase))
            return true;
        if (string.Equals(str, "false", StringComparison.OrdinalIgnoreCase))
            return false;

        throw new EvaluationException(ErrorEval.VALUE_INVALID);
    }

    // Numeric values: NaN is an error, otherwise zero = false, non‑zero = true
    if (ve is NumericValueEval numericEval)
    {
        double d = numericEval.GetNumberValue();

        if (double.IsNaN(d))
            throw new EvaluationException(ErrorEval.VALUE_INVALID);

        return d != 0;
    }

    // Propagate any error evaluation
    if (ve is ErrorEval errorEval)
        throw new EvaluationException(errorEval);

    // Anything else is unexpected
    throw new InvalidOperationException(
        $"Unexpected eval ({ve.GetType().FullName})");
}

