using System;

public static class UriValidator
{
    /// <summary>
    /// Validates a portion of a URI string.
    /// </summary>
    /// <param name="uri">The whole URI string.</param>
    /// <param name="start">The start index (inclusive) of the segment to validate.</param>
    /// <param name="end">The end index (exclusive) of the segment to validate.</param>
    /// <param name="name">A name used in exception messages (e.g., the component name).</param>
    /// <returns>The validated substring (uri.Substring(start, end‑start)).</returns>
    /// <exception cref="UriFormatException">Thrown when an illegal character or an invalid %‑escape is found.</exception>
    public static string Validate(string uri, int start, int end, string name)
    {
        for (int i = start; i < end; )
        {
            char ch = uri[i];

            // alphanumerics or retained characters are OK
            if ((ch >= 'a' && ch <= 'z') ||
                (ch >= 'A' && ch <= 'Z') ||
                (ch >= '0' && ch <= '9') ||
                IsRetained(ch))
            {
                i++;
            }
            // percent‑escape handling
            else if (ch == '%')
            {
                if (i + 2 >= end)
                {
                    throw new UriFormatException(
                        $"Incomplete % sequence in {name} at position {i}.");
                }

                int d1 = HexToInt(uri[i + 1]);
                int d2 = HexToInt(uri[i + 2]);

                if (d1 == -1 || d2 == -1)
                {
                    string seq = uri.Substring(i, 3);
                    throw new UriFormatException(
                        $"Invalid % sequence \"{seq}\" in {name} at position {i}.");
                }

                i += 3; // consumed %xy
            }
            // anything else is illegal
            else
            {
                throw new UriFormatException(
                    $"Illegal character in {name} at position {i}.");
            }
        }

        // return the validated slice
        return uri.Substring(start, end - start);
    }

    // ------------------------------------------------------------------------
    // Helper methods – you need to provide implementations that match the
    // semantics of the original Java code.
    // ------------------------------------------------------------------------

    /// <summary>
    /// Returns true if the character is one of the "reserved" characters that
    /// may appear unescaped in a URI component. Adapt the list to your needs.
    /// </summary>
    private static bool IsRetained(char c)
    {
        // Example implementation – replace with the actual set you need.
        // The Java version probably checks for characters like '-', '_', '.', '!', '~', '*', '\'', '(', ')'.
        const string retained = "-_.!~*'()";
        return retained.IndexOf(c) >= 0;
    }

    /// <summary>
    /// Converts a hexadecimal digit character to its integer value.
    /// Returns -1 if the character is not a valid hex digit.
    /// </summary>
    private static int HexToInt(char c)
    {
        if (c >= '0' && c <= '9')
            return c - '0';
        if (c >= 'a' && c <= 'f')
            return 10 + (c - 'a');
        if (c >= 'A' && c <= 'F')
            return 10 + (c - 'A');
        return -1;
    }
}

