public static string HtmlEncode(string plainText)
{
    if (string.IsNullOrEmpty(plainText))
    {
        return string.Empty;
    }

    var result = new System.Text.StringBuilder(plainText.Length);
    for (int i = 0; i < plainText.Length; i++)
    {
        char ch = plainText[i];
        switch (ch)
        {
            case '\"':
                result.Append("&quot;");
                break;
            case '&':
                result.Append("&amp;");
                break;
            case '<':
                result.Append("&lt;");
                break;
            case '>':
                result.Append("&gt;");
                break;
            case '\'':
                result.Append("&#x27;");
                break;
            case '/':
                result.Append("&#x2F;");
                break;
            default:
                result.Append(ch);
                break;
        }
    }

    return result.ToString();
}

