                update.Force = true;               // equivalent to setForceUpdate(true)

                // Execute the delete and get the result
                var deleteResult = update.Delete();

                bool ok = true;
                switch (deleteResult)
                {
                    case UpdateResult.IOFailure:
                    case UpdateResult.LockFailure:
                    case UpdateResult.Rejected:
                        ok = false;
                        break;
                    default:
